#!/usr/bin/env python3
"""Join six AlphaGenome reference/alternate prediction summaries to Brain6."""
import csv,hashlib,json
from pathlib import Path
P=Path(__file__).resolve().parent/'results'; A=P/'avi_mirror'; O=P/'jbrowse_predictions';O.mkdir(exist_ok=True)
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):
 with p.open() as f:return list(csv.DictReader(f,delimiter='\t'))
regions=read(P/'regions.tsv'); evidence=read(A/'variant_evidence_avi.tsv'); inputs=[P/'jbrowse_chr5']+sorted((P/'jbrowse_five').iterdir()); outputs=[];source_hashes={}
if len(regions)!=6 or len(inputs)!=6:raise ValueError('Expected six regions and predictions')
for folder in inputs:
 prov=json.loads((folder/'provenance.json').read_text());source_hashes[str(folder.relative_to(P))+'/provenance.json']=digest(folder/'provenance.json')
 for name,h in prov['output_sha256'].items():
  if digest(folder/name)!=h:raise ValueError(f'Prediction file hash mismatch {folder/name}')
 v=prov['request']['variant']; var=f"{v['chromosome']}:{v['position']}:{v['reference_bases']}>{v['alternate_bases']}"
 matches=[r for r in evidence if r['atlas_variant']==var and r['snp']==v['name']]
 if len(matches)!=1:raise ValueError(f'Unexpected variant identity: {var}')
 row=matches[0];cid=row['candidate_locus_id']; group=[r for r in evidence if r['candidate_locus_id']==cid]
 if sorted(group,key=lambda r:(-int(r['avi_raw_e5']),r['atlas_variant']))[0]['atlas_variant']!=var:raise ValueError('Not the preselected highest AVI variant')
 summary=read(folder/'track_summary.tsv');dna=[r for r in summary if r['output_type']=='dnase'];adult=[r for r in summary if r['output_type']=='rna_seq' and r['life_stage']=='adult' and r['data_source']=='gtex']
 if len(dna)!=1 or len(adult)!=1:raise ValueError('Expected exactly one DNase and adult GTEx track')
 d=dna[0];x=adult[0]
 outputs.append({'candidate_locus_id':cid,'snp':v['name'],'variant_grch38':var,'atlas_url':row['atlas_url'],'avi_phred_lower':row['avi_phred_lower'],'avi_phred_upper':row['avi_phred_upper'],'insomnia_abf_conditional_pip':row['insomnia_conditional_abf_pip'],'adhd_abf_conditional_pip':row['adhd_conditional_abf_pip'],'dnase_ref_sum_501bp':d['ref_sum_501bp'],'dnase_alt_sum_501bp':d['alt_sum_501bp'],'dnase_log2_ratio_501bp':d['local_log2_ratio_plus_one'],'adult_rna_ref_sum_501bp':x['ref_sum_501bp'],'adult_rna_alt_sum_501bp':x['alt_sum_501bp'],'adult_rna_local_log2_ratio_501bp':x['local_log2_ratio_plus_one'],'prediction_folder':str(folder.relative_to(P)),'status':'EXPLORATORY_REFERENCE_ALTERNATE_PREDICTION'})
if {o['candidate_locus_id'] for o in outputs}!={r['candidate_locus_id'] for r in regions}:raise ValueError('Region coverage mismatch')
order={r['candidate_locus_id']:i for i,r in enumerate(regions)};outputs.sort(key=lambda x:order[x['candidate_locus_id']])
with (O/'six_region_predictions.tsv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(outputs[0]),delimiter='\t',lineterminator='\n');w.writeheader();w.writerows(outputs)
lines=['# Brain6 × AlphaGenome: frontal-cortex prediction pilot','','**Scope:** one variant per insomnia–ADHD region, selected by the highest raw AVI score in the previously selected credible-set union. The public JBrowse service generated AlphaGenome reference and alternate sequence predictions for six variants with 1,048,576 bp sequence context. These are predictions rather than observed tissue measurements. Other variants and tissues were not predicted in this initial run. A subsequent [expanded analysis](../jbrowse_expanded/EXPANDED_REPORT.md) covers all 425 selected variants in the same tracks.','','## Chromosome 5: rs2431108','','At GRCh38 chr5:104612267:T>C, the adult frontal-cortex ENCODE DNase track has a predicted sum of 9.37010 for T and 9.37392 for C in the 501 bp window centered on the variant. The local log₂ ratio, with a pseudocount of one, is +0.000531. This near-zero value is a numerical result for this track and window; without a calibrated null, it is not evidence that the variant has no effect.','','The service also returned an adult GTEx Brain_Cortex RNA track and two strand-specific embryonic ENCODE RNA tracks. The window-level values in the table below summarize local predicted signal only. They are **not gene-expression effect scores**: no gene exon mask, transcript attribution or calibrated per-gene variant score was calculated.','','![Chromosome 5 predicted tracks](../jbrowse_chr5/predicted_tracks.svg)', '', 'The horizontal axes show base-pair offset from rs2431108; the vertical axes show predicted signal on separate scales for each track. Blue is reference T and orange is alternate C.', '', '## Six-region comparison','','| Candidate variant | GRCh38 variant | AVI PHRED range | Adult DNase log₂ ratio | Adult GTEx RNA local log₂ ratio |','|---|---|---:|---:|---:|']
for x in outputs:
 lo=float(x['avi_phred_lower']);hi=float(x['avi_phred_upper']);ph=f'{lo:.3f}' if lo==hi else f'{lo:.3f}–{hi:.3f}'
 lines.append(f"| [{x['snp']}]({x['atlas_url']}) | {x['variant_grch38']} | {ph} | {float(x['dnase_log2_ratio_501bp']):+.6f} | {float(x['adult_rna_local_log2_ratio_501bp']):+.6f} |")
lines += ['', 'For each track, the summary is log₂((sum alternate signal + 1)/(sum reference signal + 1)) over the 501 bp centered on the variant. The DNase calculation follows the local 501 bp sum-ratio form described for AlphaGenome accessibility scorers; it is calculated here from JBrowse prediction arrays, not returned by the official variant-scoring endpoint. The RNA ratio is a descriptive local window summary, not the model’s recommended gene-level RNA scorer. Both ratios are model predictions, not statistical tests. They are not calibrated to indicate significance or whether a variant mediates an insomnia–ADHD relationship.','', 'The chr3 rs62264764 adult DNase ratio is more negative than the other five in this *selected* set. This is a candidate hypothesis for further assessment, not evidence of a causal variant, a target gene, or tissue specificity. Selecting one high-AVI SNP per region does not establish that it is the best causal candidate, and this table should not be generalized to all 425 variants.','', 'The existing measured eQTL context is reported separately in `../avi_mirror/MOLECULAR_CONTEXT.md`; it must not be interpreted as validation of these predictions. Brain6’s failed primary LAVA family, model-conditional ABF colocalization and absence of independent two-trait locus replication are unchanged.','', '## Provenance and limits','', 'All requests used the frontal-cortex ontology `UBERON:0001870` and the same DNase/RNA output types. The service reported track-specific assay, tissue, life stage and source metadata in each prediction receipt. For every variant, `track_window.tsv` contains reference and alternate predictions at 2,001 bases around the variant, and `track_summary.tsv` contains four track summaries; files and extracted HTTP byte ranges are hashed in each local `provenance.json`. The service did not expose a model release identifier. A future run could therefore differ.','', 'The 1 Mb model context and GRCh38 reference/alternate alleles were verified against the request and prepared variant table. The proxy holds its own API key and is limited to non-commercial use. Inference outputs must not be used for clinical decision-making or to train another ML model. Signed URLs returned by the proxy are temporary and are not included in these artifacts.','', '[AlphaGenome model paper](https://www.nature.com/articles/s41586-025-10014-0) · [JBrowse AlphaGenome documentation](https://www.jbrowse.org/jb2/docs/tutorials/alphagenome/) · [AlphaGenome variant scoring documentation](https://github.com/google-deepmind/alphagenome/blob/main/docs/source/variant_scoring.md)','']
(O/'FRONTAL_CORTEX_REPORT.md').write_text('\n'.join(lines))
receipt={'n_regions':len(outputs),'n_variants':len(outputs),'selection':'one maximum-AVI variant from each previously selected credible-set union','inputs':source_hashes,'evidence_sha256':digest(A/'variant_evidence_avi.tsv'),'output_sha256':{x:digest(O/x) for x in ['six_region_predictions.tsv','FRONTAL_CORTEX_REPORT.md']},'track_types':'adult frontal-cortex ENCODE DNase; adult GTEx Brain_Cortex RNA; two embryonic ENCODE RNA strands','experimental_status':'predictions, not independently validated tissue or trait effects','service_model_release':'not provided'}
(O/'provenance.json').write_text(json.dumps(receipt,indent=2,sort_keys=True)+'\n')
print(f"Compiled {len(outputs)} region predictions")
